from sympy import symbols, Poly, expand

def check_good_sequence(a, b):
    """
    Checks if the sequence (a, b) forms a good sequence for N=2.
    a = (a0, a1, a2), b = (b0, b1, b2)
    """
    if sum(a) != 3 or sum(b) != 3:
        return False

    x = symbols('x')

    # Equation 1: P_a(x) = Q_a(x)
    P_a = (x - a[0]) * (x - a[1]) * (x - a[2])

    Q_a = x**b[0] * (x - 1)**b[1] * (x - 2)**b[2]

    # Equation 2: P_b(x) = Q_b(x)
    P_b = (x - b[0]) * (x - b[1]) * (x - b[2])

    Q_b = x**a[0] * (x - 1)**a[1] * (x - 2)**a[2]

    # Check equality of polynomials
    if P_a != Q_a:
        return False

    if P_b != Q_b:
        return False

    return True

# Search bounds (a_i, b_i are integers)
# Since sum must be 3, values don't need to be huge, but let's use a generous bound.
BOUND = 5

solutions_a = []
solutions_b = []

# Iterate over all combinations for A = (a0, a1, a2)
for a0 in range(-BOUND, BOUND + 1):
    for a1 in range(-BOUND, BOUND + 1):
        for a2 in range(-BOUND, BOUND + 1):
            if a0 + a1 + a2 == 3:
                A = (a0, a1, a2)
                solutions_a.append(A)

# Iterate over all combinations for B = (b0, b1, b2)
for b0 in range(-BOUND, BOUND + 1):
    for b1 in range(-BOUND, BOUND + 1):
        for b2 in range(-BOUND, BOUND + 1):
            if b0 + b1 + b2 == 3:
                B = (b0, b1, b2)
                solutions_b.append(B)

# Check all pairings
found_solutions = []
for A in solutions_a:
    for B in solutions_b:
        if check_good_sequence(A, B):
            found_solutions.append((A, B))

print(f"Total solutions found in search range (BOUND={BOUND}): {len(found_solutions)}")
for i, (A, B) in enumerate(found_solutions):
    print(f"Solution {i+1}: A={A}, B={B}")

def get_prime_factors(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

n = 499499
factors = get_prime_factors(n)
print(f"Prime factorization of {n}: {factors}")

def is_prime(n):
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

print(f"Is 499499 prime? {is_prime(499499)}")
